 hook=dict(entityAtFrame0='Air memasuki basement dan mendorong kursi.',peakVisual='Kilas air dan kursi dari banjir B6, jelas berlabel rekonstruksi ilustratif.',openingLine='Banjir datang dari bawah.',cutQuestion='Dari mana air bisa masuk saat jalan di atas kering?',climaxBeatId='B6',answerBeatId='B6',visualCutSeconds=None,spokenOpeningSeconds=None),
