def package(items, script_id, fname):
    script = dict(id=script_id, status='DRAFT PRIVATE — belum review manusia', scenes=[dict(id=s['id'],narration=' '.join(l['text'] for l in s['lines'])) for s in items])
    review_items=[]
    for s in items:
        for l in s['lines']:
            review_items.append(dict(sceneId=s['id'], **l, connection=s['connection']))
    audit = dict(scriptId=script_id,audienceAnchor=dict(situation='Air di ruang kerja dan laporan yang berpindah tangan.',scope='Analogi terbatas: tidak mengasumsikan setiap penonton pernah bekerja di kantor atau mengalami banjir.'),items=review_items)
    (ROOT/f'{fname}.script.json').write_text(json.dumps(script,ensure_ascii=False,indent=2)+'\n')
    (ROOT/f'{fname}.audit.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2)+'\n')
    return script

master=package(scenes,brief['scriptId'],'master')
