def storyboard(items,title):
    out=[f'# {title}', '', 'Status: DRAFT PRIVAT / REKONSTRUKSI ILUSTRATIF. Durasi & subtitle menunggu ukuran nyata dan review.', '', '| Scene | Beat | Narasi | Visual dan gerak yang direncanakan | ObjectMap |', '|---|---|---|---|---|']
    for s in items:
        nar=' '.join(l['text'] for l in s['lines'])
        ob='; '.join(f"{o['object']} → {o['action']}" for o in s['objects'])
        out.append(f"| {s['id']} | {s['beat']} | {nar} | {s['framing']} Aset: {s['asset']}. | {ob} |")
    return '\n'.join(out)+'\n'
(ROOT/'storyboard-master.md').write_text(storyboard(scenes,'Storyboard master — Banjir dari Bawah'),encoding='utf-8')
(ROOT/'storyboard-short.md').write_text(storyboard(short,'Storyboard Short — Peringatan Sebelum Banjir'),encoding='utf-8')

def script_text(items,title):
    out=[f'# {title}', '', 'DRAFT PRIVAT — naskah belum mendapat review manusia dan bukan izin tayang.', '']
    for s in items:
        out += [f"## {s['id']}", ' '.join(l['text'] for l in s['lines']), '']
    return '\n'.join(out)
(ROOT/'naskah-master.md').write_text(script_text(scenes,'Naskah master — Banjir dari Bawah'),encoding='utf-8')
(ROOT/'naskah-short.md').write_text(script_text(short,'Naskah Short — Peringatan Sebelum Banjir'),encoding='utf-8')
